head.script:
scwin.screenId = "jldfil17102";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "txa_content", attr: "label", fn: function () { return String(dma_qnaResultDetail.get("quesContn")); } },
        { childId: "td_40", attr: "__html", fn: function () { return ([String(String(String(dma_qnaResultDetail.get("ansContn"))).split(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("NEW_LINE")))).join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(String(dma_qnaResultDetail.get("ansContn"))).split(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("NEW_LINE")))).join("<br/>"))) : ''); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_28_txt", fn: function(){ return (!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'); } }, { id: "c_otherwise_29", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'))); } }, { id: "c_otherwise_36", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '완료'))); } }, { id: "if_ansProgStatCd", fn: function(){ return (!(String(((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })())) == null ? '' : ((dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()))).length === 0) && (dma_qnaResultDetail.get("ansProgStatCd") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.ansProgStatCd"); })()) === '처리중'); } }, { id: "c_when_57", fn: function(){ return (!(String(((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })()))).length === 0)); } }, { id: "c_otherwise_61", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("nextQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.nextQnaResultVO"); })()))).length === 0)))); } }, { id: "c_when_69", fn: function(){ return (!(String(((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })()))).length === 0)); } }, { id: "c_otherwise_73", fn: function(){ return (!((!(String(((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })())) == null ? '' : ((dma_qnaResultDetail.get("preQnaResultVO") ?? (() => { throw new Error("unresolved:" + "qnaResultDetail.preQnaResultVO"); })()))).length === 0)))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil17102.onpageload' });
    }
};


