///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param flag contnId
 * @returns
 * @hidden N
*/
scwin.goURL = async function (flag, contnId) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchQnaResult');
        (document.qnaResultDetailForm || { elements: [] }).action = 'qna.do';
        { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult', "contnId": contnId }); } };
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchQnaResultDetail');
            $c.util.getComponent('dma_GoURLReq').set('contnId', contnId);
            (document.qnaResultDetailForm || { elements: [] }).action = 'qna.do';
            { const __nr = await scwin.tx_fn_GoURL(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17101/jldfil17101.xml", { "method": 'searchQnaResult', "contnId": contnId }); } };
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param quesID
 * @returns
 * @hidden N
*/
scwin.modify = async function (quesID) {
    /* sdd-asis-lifecycle:begin fn_Modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.qnaResultDetailForm || { elements: [] });
    $c.util.getComponent('dma_GoURLReq').set('contnId', quesID);
    await scwin.checkByte($c.util.getComponent('txa_content'));
    frm.action = 'qna.do';
    $c.util.getComponent('dma_GoURLReq').set('method', 'updateQna');
    await scwin.tx_fn_Modify();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteGoURLReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param quesID
 * @returns
 * @hidden N
*/
scwin.deleteGoURLReq = async function (quesID) {
    /* sdd-asis-lifecycle:begin fn_Delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("정말 삭제하시겠습니까?") === true) {
        const frm = (document.qnaResultDetailForm || { elements: [] });
        $c.util.getComponent('dma_GoURLReq').set('contnId', quesID);
        frm.action = 'qna.do';
        $c.util.getComponent('dma_GoURLReq').set('method', 'deleteQna');
        await scwin.tx_fn_Delete();
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 1990;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "질의내용(" + (contnByte) + "/2000 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getByte = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            iCounts++;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcContn
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn _maximum
 * @returns
 * @hidden N
*/
scwin.calcContn = function (_contn, _maximum) {
    /* sdd-asis-lifecycle:begin fn_CalcContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0D') {
            inc = 1;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
    /* sdd-asis-lifecycle:end */
};
